CREATE TABLE swap_quotes(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),from_asset text NOT NULL,to_asset text NOT NULL,input_atoms numeric(78,0) NOT NULL CHECK(input_atoms>0),output_atoms numeric(78,0) NOT NULL CHECK(output_atoms>0),pricing jsonb NOT NULL,expires_at timestamptz NOT NULL,used boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(from_asset<>to_asset));
CREATE TABLE swap_orders(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),quote_id uuid NOT NULL UNIQUE REFERENCES swap_quotes(id),idempotency_key uuid NOT NULL,from_asset text NOT NULL,to_asset text NOT NULL,input_atoms numeric(78,0) NOT NULL,output_atoms numeric(78,0) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
